17	// statusStyles holds pre-built lipgloss styles and terminal metadata.
18	type statusStyles struct {
19		colorEnabled bool
20		width        int
21	
22		// Styles
23		green  lipgloss.Style
24		red    lipgloss.Style
25		gray   lipgloss.Style
26		bold   lipgloss.Style
27		dim    lipgloss.Style
28		agent  lipgloss.Style // amber/orange for agent names
29		cyan   lipgloss.Style
30		yellow lipgloss.Style // yellow for stale warnings
31	}
32	
33	// newStatusStyles creates styles appropriate for the output writer.
34	func newStatusStyles(w io.Writer) statusStyles {
35		useColor := shouldUseColor(w)
36		width := getTerminalWidth(w)
37	
38		s := statusStyles{
39			colorEnabled: useColor,
40			width:        width,
41		}
42	
43		if useColor {
44			s.green = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
45			s.red = lipgloss.NewStyle().Foreground(lipgloss.Color("1"))
46			s.gray = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
47			s.bold = lipgloss.NewStyle().Bold(true)
48			s.dim = lipgloss.NewStyle().Faint(true)
49			s.agent = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("214"))
50			s.cyan = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
51			s.yellow = lipgloss.NewStyle().Foreground(lipgloss.Color("3"))
52		}
53	
54		return s
55	}
56	
57	// render applies a style to text only when color is enabled.
58	func (s statusStyles) render(style lipgloss.Style, text string) string {
59		if !s.colorEnabled {
60			return text
61		}
62		return style.Render(text)
63	}
64	
65	// isTerminalWriter returns true if the writer is connected to a terminal.
66	func isTerminalWriter(w io.Writer) bool {
67		if f, ok := w.(*os.File); ok {
68			return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
69		}
70		return false
71	}
72	
73	// shouldUseColor returns true if the writer supports color output.
74	func shouldUseColor(w io.Writer) bool {
75		if os.Getenv("NO_COLOR") != "" {
76			return false
77		}
78		return isTerminalWriter(w)
79	}
80	
81	// getTerminalWidth returns the terminal width, capped at 80 with a fallback of 60.
82	// It first checks the writer itself, then falls back to Stdout/Stderr.
83	func getTerminalWidth(w io.Writer) int {
84		// Try the output writer first
85		if f, ok := w.(*os.File); ok {
86			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
87				return min(width, 80)
88			}
89		}
90	
91		// Fall back to Stdout, then Stderr
92		for _, f := range []*os.File{os.Stdout, os.Stderr} {
93			if f == nil {
94				continue
95			}
96			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
97				return min(width, 80)
98			}
99		}
100	
101		return 60
102	}
103	
104	// formatTokenCount formats a token count for display.
105	// 0 → "0", 500 → "500", 1200 → "1.2k", 14300 → "14.3k"
106	func formatTokenCount(n int) string {
107		if n < 1000 {
108			return strconv.Itoa(n)
109		}
110		f := float64(n) / 1000.0
111		s := fmt.Sprintf("%.1f", f)
112		// Remove trailing ".0" for clean display (e.g., 1000 → "1k" not "1.0k")
113		s = strings.TrimSuffix(s, ".0")
114		return s + "k"
115	}
116	
117	// totalTokens recursively sums all token fields including subagent tokens.
118	func totalTokens(tu *agent.TokenUsage) int {
119		if tu == nil {
120			return 0
121		}
122		total := tu.InputTokens + tu.CacheCreationTokens + tu.CacheReadTokens + tu.OutputTokens
123		total += totalTokens(tu.SubagentTokens)
124		return total
125	}
126	
127	// horizontalRule renders a dimmed horizontal rule of the given width.
128	func (s statusStyles) horizontalRule(width int) string {
129		rule := strings.Repeat("─", width)
130		return s.render(s.dim, rule)
131	}
132	
133	// sectionRule renders a section header like: ── Active Sessions ────────────
134	func (s statusStyles) sectionRule(label string, width int) string {
135		prefix := "── "
136		content := label + " "
137		usedWidth := len([]rune(prefix)) + len([]rune(content))
138		trailing := width - usedWidth
139		if trailing < 1 {
140			trailing = 1
141		}
142	
143		var b strings.Builder
144		b.WriteString(s.render(s.dim, "── "))
145		b.WriteString(s.render(s.dim, label))
146		b.WriteString(" ")
147		b.WriteString(s.render(s.dim, strings.Repeat("─", trailing)))
148		return b.String()
149	}
150	
151	// activeTimeDisplay formats a last interaction time for display.
152	// Returns "active now" for recent activity (<1min), otherwise "active Xm ago".
153	func activeTimeDisplay(lastInteraction *time.Time) string {
154		if lastInteraction == nil {
155			return ""
156		}
157		d := time.Since(*lastInteraction)
158		if d < time.Minute {
159			return "active now"
160		}
161		return "active " + timeAgo(*lastInteraction)
162	}
