11	// NewAuthenticatedAPIClient creates an API client using the bearer token
12	// from the CLI login flow. Returns an error if the user is not logged in.
13	// Pass insecureHTTP=true to allow plain HTTP base URLs (for local development).
14	func NewAuthenticatedAPIClient(insecureHTTP bool) (*api.Client, error) {
15		token, err := auth.LookupCurrentToken()
16		if err != nil {
17			return nil, fmt.Errorf("lookup auth token: %w", err)
18		}
19		if token == "" {
20			return nil, errors.New("not logged in (run 'entire login' first)")
21		}
22	
23		if !insecureHTTP {
24			if err := api.RequireSecureURL(api.BaseURL()); err != nil {
25				return nil, fmt.Errorf("base URL check: %w", err)
26			}
27		}
28		return api.NewClient(token), nil
29	}
