33	func newStatusCmd() *cobra.Command {
34		var detailed bool
35		var jsonFlag bool
36	
37		cmd := &cobra.Command{
38			Use:   "status",
39			Short: "Show Entire status",
40			Long:  "Show whether Entire is currently enabled or disabled",
41			RunE: func(cmd *cobra.Command, _ []string) error {
42				return runStatus(cmd.Context(), cmd.OutOrStdout(), detailed, jsonFlag)
43			},
44		}
45	
46		cmd.Flags().BoolVar(&detailed, "detailed", false, "Show detailed status for each settings file")
47		cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output as JSON")
48		cmd.MarkFlagsMutuallyExclusive("detailed", "json")
49	
50		return cmd
51	}
