53	func runStatus(ctx context.Context, w io.Writer, detailed, jsonOutput bool) error {
54		if jsonOutput {
55			return runStatusJSON(ctx, w)
56		}
57	
58		// Check if we're in a git repository
59		if _, repoErr := paths.WorktreeRoot(ctx); repoErr != nil {
60			fmt.Fprintln(w, "✕ not a git repository")
61			return nil //nolint:nilerr // Not being in a git repo is a valid status, not an error
62		}
63	
64		// Get absolute paths for settings files
65		settingsPath, err := paths.AbsPath(ctx, EntireSettingsFile)
66		if err != nil {
67			settingsPath = EntireSettingsFile
68		}
69		localSettingsPath, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
70		if err != nil {
71			localSettingsPath = EntireSettingsLocalFile
72		}
73	
74		// Check which settings files exist
75		_, projectErr := os.Stat(settingsPath)
76		if projectErr != nil && !errors.Is(projectErr, fs.ErrNotExist) {
77			return fmt.Errorf("cannot access project settings file: %w", projectErr)
78		}
79		_, localErr := os.Stat(localSettingsPath)
80		if localErr != nil && !errors.Is(localErr, fs.ErrNotExist) {
81			return fmt.Errorf("cannot access local settings file: %w", localErr)
82		}
83		projectExists := projectErr == nil
84		localExists := localErr == nil
85	
86		if !projectExists && !localExists {
87			fmt.Fprintln(w, "○ not set up (run `entire enable` to get started)")
88			return nil
89		}
90	
91		sty := newStatusStyles(w)
92	
93		if detailed {
94			return runStatusDetailed(ctx, w, sty, settingsPath, localSettingsPath, projectExists, localExists)
95		}
96	
97		// Short output: just show the effective/merged state
98		s, err := LoadEntireSettings(ctx)
99		if err != nil {
100			return fmt.Errorf("failed to load settings: %w", err)
101		}
102	
103		fmt.Fprintln(w, formatSettingsStatusShort(ctx, s, sty))
104		if s.Enabled {
105			writeActiveSessions(ctx, w, sty)
106		}
107	
108		return nil
109	}
