111	// runStatusDetailed shows the effective status plus detailed status for each settings file.
112	func runStatusDetailed(ctx context.Context, w io.Writer, sty statusStyles, settingsPath, localSettingsPath string, projectExists, localExists bool) error {
113		// First show the effective/merged status
114		effectiveSettings, err := LoadEntireSettings(ctx)
115		if err != nil {
116			return fmt.Errorf("failed to load settings: %w", err)
117		}
118		fmt.Fprintln(w, formatSettingsStatusShort(ctx, effectiveSettings, sty))
119		fmt.Fprintln(w) // blank line
120	
121		// Show project settings if it exists
122		if projectExists {
123			projectSettings, err := settings.LoadFromFile(settingsPath)
124			if err != nil {
125				return fmt.Errorf("failed to load project settings: %w", err)
126			}
127			fmt.Fprintln(w, formatSettingsStatus("Project", projectSettings, sty))
128		}
129	
130		// Show local settings if it exists
131		if localExists {
132			localSettings, err := settings.LoadFromFile(localSettingsPath)
133			if err != nil {
134				return fmt.Errorf("failed to load local settings: %w", err)
135			}
136			fmt.Fprintln(w, formatSettingsStatus("Local", localSettings, sty))
137		}
138	
139		if effectiveSettings.Enabled {
140			writeActiveSessions(ctx, w, sty)
141		}
142	
143		return nil
144	}
