146	// formatSettingsStatusShort formats a short settings status line.
147	// Output format: "● Enabled · manual-commit · branch main" or "○ Disabled"
148	func formatSettingsStatusShort(ctx context.Context, s *EntireSettings, sty statusStyles) string {
149		displayName := strategy.StrategyNameManualCommit
150	
151		var b strings.Builder
152	
153		if s.Enabled {
154			b.WriteString(sty.render(sty.green, "●"))
155			b.WriteString(" ")
156			b.WriteString(sty.render(sty.bold, "Enabled"))
157		} else {
158			b.WriteString(sty.render(sty.red, "○"))
159			b.WriteString(" ")
160			b.WriteString(sty.render(sty.bold, "Disabled"))
161		}
162	
163		b.WriteString(sty.render(sty.dim, " · "))
164		b.WriteString(displayName)
165	
166		// Resolve branch from repo root
167		if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
168			if branch := resolveWorktreeBranch(ctx, repoRoot); branch != "" {
169				b.WriteString(sty.render(sty.dim, " · "))
170				b.WriteString("branch ")
171				b.WriteString(sty.render(sty.cyan, branch))
172			}
173		}
174	
175		// Show enabled agents
176		if s.Enabled {
177			if displayNames := InstalledAgentDisplayNames(ctx); len(displayNames) > 0 {
178				b.WriteString("\n")
179				b.WriteString(sty.render(sty.dim, "  Agents · "))
180	
181				b.WriteString(strings.Join(displayNames, ", "))
182			}
183		}
184	
185		return b.String()
186	}
