209	// timeAgo formats a time as a human-readable relative duration.
210	func timeAgo(t time.Time) string {
211		d := time.Since(t)
212		switch {
213		case d < time.Minute:
214			return "just now"
215		case d < time.Hour:
216			m := int(d.Minutes())
217			return fmt.Sprintf("%dm ago", m)
218		case d < 24*time.Hour:
219			h := int(d.Hours())
220			return fmt.Sprintf("%dh ago", h)
221		default:
222			days := int(d.Hours() / 24)
223			return fmt.Sprintf("%dd ago", days)
224		}
225	}
