227	// worktreeGroup groups sessions by worktree path for display.
228	type worktreeGroup struct {
229		path     string
230		branch   string
231		sessions []*session.State
232	}
233	
234	const (
235		unknownPlaceholder  = "(unknown)"
236		detachedHEADDisplay = "HEAD"
237	)
238	
239	// writeActiveSessions writes active session information grouped by worktree.
240	func writeActiveSessions(ctx context.Context, w io.Writer, sty statusStyles) {
241		store, err := session.NewStateStore(ctx)
242		if err != nil {
243			return
244		}
245	
246		states, err := store.List(ctx)
247		if err != nil || len(states) == 0 {
248			return
249		}
250	
251		// Filter to active sessions only
252		var active []*session.State
253		for _, s := range states {
254			if s.EndedAt == nil {
255				active = append(active, s)
256			}
257		}
258		if len(active) == 0 {
259			return
260		}
261	
262		repoRoot, head, headErr := currentHeadLinkage(ctx)
263		divergenceWarnings := make(map[string]string)
264		if headErr == nil && repoRoot != "" && head.commitHash != "" {
265			divergenceWarnings = computeSessionDivergenceWarnings(repoRoot, active, head)
266		}
267	
268		// Group by worktree path
269		groups := make(map[string]*worktreeGroup)
270		for _, s := range active {
271			wp := s.WorktreePath
272			if wp == "" {
273				wp = unknownPlaceholder
274			}
275			g, ok := groups[wp]
276			if !ok {
277				g = &worktreeGroup{path: wp}
278				groups[wp] = g
279			}
280			g.sessions = append(g.sessions, s)
281		}
282	
283		// Resolve branch names for each worktree (skip for unknown paths)
284		for _, g := range groups {
285			if g.path != unknownPlaceholder {
286				g.branch = resolveWorktreeBranch(ctx, g.path)
287			}
288		}
289	
290		// Sort groups: alphabetical by path
291		sortedGroups := make([]*worktreeGroup, 0, len(groups))
292		for _, g := range groups {
293			sortedGroups = append(sortedGroups, g)
294		}
295		sort.Slice(sortedGroups, func(i, j int) bool {
296			return sortedGroups[i].path < sortedGroups[j].path
297		})
298	
299		// Sort sessions within each group by StartedAt (newest first)
300		for _, g := range sortedGroups {
301			sort.Slice(g.sessions, func(i, j int) bool {
302				return g.sessions[i].StartedAt.After(g.sessions[j].StartedAt)
303			})
304		}
305	
306		// Track aggregate totals
307		var totalSessions int
308	
309		fmt.Fprintln(w)
310		printedHeader := false
311		for _, g := range sortedGroups {
312			if !printedHeader {
313				fmt.Fprintln(w, sty.sectionRule("Active Sessions", sty.width))
314				fmt.Fprintln(w)
315				printedHeader = true
316			}
317	
318			for _, st := range g.sessions {
319				totalSessions++
320	
321				agentLabel := string(st.AgentType)
322				if agentLabel == "" {
323					agentLabel = unknownPlaceholder
324				}
325	
326				// Line 1: Agent (model) · sessionID
327				if st.ModelName != "" {
328					fmt.Fprintf(w, "%s %s %s %s\n",
329						sty.render(sty.agent, agentLabel),
330						sty.render(sty.dim, "("+st.ModelName+")"),
331						sty.render(sty.dim, "·"),
332						st.SessionID)
333				} else {
334					fmt.Fprintf(w, "%s %s %s\n",
335						sty.render(sty.agent, agentLabel),
336						sty.render(sty.dim, "·"),
337						st.SessionID)
338				}
339	
340				// Line 2: > "first prompt" (chevron + quoted, truncated)
341				if st.LastPrompt != "" {
342					prompt := stringutil.TruncateRunes(st.LastPrompt, 60, "...")
343					fmt.Fprintf(w, "%s \"%s\"\n", sty.render(sty.dim, ">"), prompt)
344				}
345	
346				// Line 3: stats line — started Xd ago · active now · files N · tokens X.Xk
347				var stats []string
348				stats = append(stats, "started "+timeAgo(st.StartedAt))
349	
350				if st.LastInteractionTime != nil && st.LastInteractionTime.Sub(st.StartedAt) > time.Minute {
351					stats = append(stats, activeTimeDisplay(st.LastInteractionTime))
352				}
353	
354				if t := totalTokens(st.TokenUsage); t > 0 {
355					stats = append(stats, "tokens "+formatTokenCount(t))
356				}
357	
358				statsLine := strings.Join(stats, sty.render(sty.dim, " · "))
359				if st.IsStuckActive() {
360					fmt.Fprintf(w, "%s %s %s\n", sty.render(sty.dim, statsLine),
361						sty.render(sty.dim, "·"),
362						sty.render(sty.yellow, "stale")+" (run 'entire doctor')")
363				} else {
364					fmt.Fprintln(w, sty.render(sty.dim, statsLine))
365				}
366				if warning := divergenceWarnings[st.SessionID]; warning != "" {
367					fmt.Fprintf(w, "%s %s\n", sty.render(sty.yellow, "!"), sty.render(sty.yellow, warning))
368				}
369				fmt.Fprintln(w)
370			}
371		}
372	
373		// Footer: horizontal rule + session count
374		fmt.Fprintln(w, sty.horizontalRule(sty.width))
375		var footer string
376		if totalSessions == 1 {
377			footer = "1 session"
378		} else {
379			footer = fmt.Sprintf("%d sessions", totalSessions)
380		}
381		fmt.Fprintln(w, sty.render(sty.dim, footer))
382		fmt.Fprintln(w)
383	}
