385	// resolveWorktreeBranch resolves the current branch for a worktree path
386	// by reading the HEAD ref directly from the filesystem
387	func resolveWorktreeBranch(ctx context.Context, worktreePath string) string {
388		gitPath := filepath.Join(worktreePath, ".git")
389	
390		fi, err := os.Stat(gitPath)
391		if err != nil {
392			return ""
393		}
394	
395		var headPath string
396		if fi.IsDir() {
397			// Regular repo: .git is a directory
398			headPath = filepath.Join(gitPath, "HEAD")
399		} else {
400			// Worktree: .git is a file containing "gitdir: <path>"
401			data, err := os.ReadFile(gitPath) //nolint:gosec // path derived from known worktree dir
402			if err != nil {
403				return ""
404			}
405			content := strings.TrimSpace(string(data))
406			if !strings.HasPrefix(content, "gitdir: ") {
407				return ""
408			}
409			gitdirPath := strings.TrimPrefix(content, "gitdir: ")
410			if !filepath.IsAbs(gitdirPath) {
411				gitdirPath = filepath.Join(worktreePath, gitdirPath)
412			}
413			headPath = filepath.Join(gitdirPath, "HEAD")
414		}
415	
416		data, err := os.ReadFile(headPath) //nolint:gosec // path constructed from .git/HEAD
417		if err != nil {
418			return ""
419		}
420	
421		ref := strings.TrimSpace(string(data))
422	
423		// Symbolic ref: "ref: refs/heads/<branch>"
424		if strings.HasPrefix(ref, "ref: refs/heads/") {
425			branch := strings.TrimPrefix(ref, "ref: refs/heads/")
426			// Reftable ref storage uses "ref: refs/heads/.invalid" as a dummy HEAD stub.
427			// Fall back to git to resolve the actual branch in that case.
428			if branch == ".invalid" {
429				return resolveWorktreeBranchGit(ctx, worktreePath)
430			}
431			return branch
432		}
433	
434		// Detached HEAD or other ref type
435		return detachedHEADDisplay
436	}
437	
438	// resolveWorktreeBranchGit resolves the branch name by shelling out to git.
439	// Used as a fallback for reftable ref storage where .git/HEAD is a stub.
440	func resolveWorktreeBranchGit(ctx context.Context, worktreePath string) string {
441		ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
442		defer cancel()
443		cmd := exec.CommandContext(ctx, "git", "-C", worktreePath, "rev-parse", "--symbolic-full-name", "HEAD")
444		out, err := cmd.Output()
445		if err != nil {
446			return detachedHEADDisplay
447		}
448		ref := strings.TrimSpace(string(out))
449		if strings.HasPrefix(ref, "refs/heads/") {
450			return strings.TrimPrefix(ref, "refs/heads/")
451		}
452		return detachedHEADDisplay
453	}
454	
455	func currentHeadLinkage(ctx context.Context) (string, headLinkage, error) {
456		repoRoot, err := paths.WorktreeRoot(ctx)
457		if err != nil {
458			return "", headLinkage{}, fmt.Errorf("resolve worktree root: %w", err)
459		}
460	
461		repo, err := git.PlainOpen(repoRoot)
462		if err != nil {
463			return "", headLinkage{}, fmt.Errorf("open repo: %w", err)
464		}
465	
466		headRef, err := repo.Head()
467		if err != nil {
468			return "", headLinkage{}, fmt.Errorf("resolve HEAD: %w", err)
469		}
470	
471		commit, err := repo.CommitObject(headRef.Hash())
472		if err != nil {
473			return "", headLinkage{}, fmt.Errorf("load HEAD commit: %w", err)
474		}
475	
476		head := headLinkage{commitHash: headRef.Hash().String()}
477		if checkpointIDs := trailers.ParseAllCheckpoints(commit.Message); len(checkpointIDs) > 0 {
478			head.checkpointIDs = make([]string, 0, len(checkpointIDs))
479			for _, checkpointID := range checkpointIDs {
480				head.checkpointIDs = append(head.checkpointIDs, checkpointID.String())
481			}
482		}
483	
484		return repoRoot, head, nil
485	}
486	
487	func computeSessionDivergenceWarnings(
488		repoRoot string,
489		active []*session.State,
490		head headLinkage,
491	) map[string]string {
492		warnings := make(map[string]string)
493		normalizedRepoRoot := normalizeWorktreePath(repoRoot)
494	
495		for _, st := range active {
496			if normalizeWorktreePath(st.WorktreePath) != normalizedRepoRoot {
497				continue
498			}
499	
500			if st.BaseCommit == "" {
501				// Session linkage is incomplete (migration refuses to run and save-step
502				// must reinitialize). Surface this explicitly rather than skipping silently,
503				// so operators don't see a false-clean status for a session that cannot
504				// be attributed until the next prompt reinitializes it.
505				warnings[st.SessionID] = "session linkage incomplete; awaiting reinitialization"
506				continue
507			}
508	
509			if st.BaseCommit == head.commitHash {
510				if st.AttributionBaseCommit != "" && st.AttributionBaseCommit != st.BaseCommit {
511					warnings[st.SessionID] = "attribution base diverged after history movement; figures may be off until next checkpoint"
512				}
513				continue
514			}
515	
516			// BaseCommit != HEAD — hooks haven't reconciled/migrated yet
517			if len(head.checkpointIDs) > 0 {
518				warnings[st.SessionID] = "tracking diverged from current HEAD; HEAD links to checkpoint(s) " + strings.Join(head.checkpointIDs, ", ")
519				continue
520			}
521	
522			warnings[st.SessionID] = "tracking diverged from current HEAD after git history movement"
523		}
524	
525		return warnings
526	}
527	
528	func normalizeWorktreePath(path string) string {
529		if path == "" {
530			return ""
531		}
532		if resolved, err := filepath.EvalSymlinks(path); err == nil {
533			return filepath.Clean(resolved)
534		}
535		return filepath.Clean(path)
536	}
