538	// statusJSON is the JSON output for `entire status --json`.
539	type statusJSON struct {
540		Enabled        bool               `json:"enabled"`
541		Agents         []string           `json:"agents"`
542		ActiveSessions []sessionBriefJSON `json:"active_sessions"`
543		Error          string             `json:"error,omitempty"`
544	}
545	
546	type sessionBriefJSON struct {
547		Agent  string `json:"agent"`
548		Model  string `json:"model,omitempty"`
549		Status string `json:"status"`
550	}
551	
552	func runStatusJSON(ctx context.Context, w io.Writer) error {
553		writeJSON := func(v statusJSON) error {
554			return json.NewEncoder(w).Encode(v)
555		}
556	
557		if _, err := paths.WorktreeRoot(ctx); err != nil {
558			return writeJSON(statusJSON{Error: "not a git repository"})
559		}
560	
561		settingsPath, err := paths.AbsPath(ctx, EntireSettingsFile)
562		if err != nil {
563			settingsPath = EntireSettingsFile
564		}
565		localSettingsPath, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
566		if err != nil {
567			localSettingsPath = EntireSettingsLocalFile
568		}
569	
570		_, projectErr := os.Stat(settingsPath)
571		if projectErr != nil && !errors.Is(projectErr, fs.ErrNotExist) {
572			return writeJSON(statusJSON{Error: fmt.Sprintf("cannot access project settings file: %v", projectErr)})
573		}
574		_, localErr := os.Stat(localSettingsPath)
575		if localErr != nil && !errors.Is(localErr, fs.ErrNotExist) {
576			return writeJSON(statusJSON{Error: fmt.Sprintf("cannot access local settings file: %v", localErr)})
577		}
578	
579		if projectErr != nil && localErr != nil {
580			return writeJSON(statusJSON{Error: "not set up"})
581		}
582	
583		s, err := LoadEntireSettings(ctx)
584		if err != nil {
585			return writeJSON(statusJSON{Error: fmt.Sprintf("failed to load settings: %v", err)})
586		}
587	
588		result := statusJSON{
589			Enabled:        s.Enabled,
590			Agents:         []string{},
591			ActiveSessions: []sessionBriefJSON{},
592		}
593	
594		if s.Enabled {
595			if names := InstalledAgentDisplayNames(ctx); len(names) > 0 {
596				result.Agents = names
597			}
598	
599			if store, err := session.NewStateStore(ctx); err == nil {
600				if states, err := store.List(ctx); err == nil {
601					// Deduplicate by agent: one entry per agent, "active" wins over "idle".
602					type agentEntry struct {
603						brief    sessionBriefJSON
604						isActive bool
605					}
606					byAgent := make(map[string]*agentEntry)
607					for _, st := range states {
608						if st.EndedAt != nil {
609							continue
610						}
611						agent := string(st.AgentType)
612						if agent == "" {
613							agent = unknownPlaceholder
614						}
615						active := st.Phase == session.PhaseActive
616						if existing, ok := byAgent[agent]; ok {
617							if active && !existing.isActive {
618								existing.brief.Model = st.ModelName
619								existing.brief.Status = sessionStatusLabel(st)
620								existing.isActive = true
621							}
622						} else {
623							byAgent[agent] = &agentEntry{
624								brief: sessionBriefJSON{
625									Agent:  agent,
626									Model:  st.ModelName,
627									Status: sessionStatusLabel(st),
628								},
629								isActive: active,
630							}
631						}
632					}
633					for _, e := range byAgent {
634						result.ActiveSessions = append(result.ActiveSessions, e.brief)
635					}
636					sort.Slice(result.ActiveSessions, func(i, j int) bool {
637						return result.ActiveSessions[i].Agent < result.ActiveSessions[j].Agent
638					})
639				}
640			}
641		}
642	
643		return writeJSON(result)
644	}
645	
646	// sessionStatusLabel derives a display status from a session state.
647	func sessionStatusLabel(s *session.State) string {
648		if s.EndedAt != nil {
649			return "ended"
650		}
651		if s.Phase != "" {
652			return string(s.Phase)
653		}
654		return string(session.PhaseIdle)
655	}
