package cli

// API response types for the /api/v1/cache/user/* endpoints used by `entire stats`.

// userCheckpoint represents a single checkpoint returned by the checkpoints API.
type userCheckpoint struct {
	CheckpointID string  `json:"checkpoint_id"`
	CommitSHA    string  `json:"commit_sha"`
	CommitMsg    string  `json:"commit_message"`
	CommitDate   string  `json:"commit_date"`
	Additions    int     `json:"additions"`
	Deletions    int     `json:"deletions"`
	FilesChanged int     `json:"files_changed"`
	RepoFullName string  `json:"repo_full_name"`
	Branch       string  `json:"branch"`
	IsPrivate    bool    `json:"is_private"`
	Agent        *string `json:"agent"`
	Steps        *int    `json:"steps"`
	SessionCount *int    `json:"session_count"`
	InputTokens  *int    `json:"input_tokens"`
	OutputTokens *int    `json:"output_tokens"`
}

// userCheckpointsResponse is the API response for GET /api/v1/cache/user/checkpoints.
type userCheckpointsResponse struct {
	Checkpoints []userCheckpoint `json:"checkpoints"`
	StreakDates []string         `json:"streakDates"`
	Timeframe   string           `json:"timeframe"`
	UpdatedAt   string           `json:"updated_at"`
}

// userCommitCheckpoint is checkpoint info nested inside a commit.
type userCommitCheckpoint struct {
	CheckpointID string   `json:"checkpoint_id"`
	Prompt       *string  `json:"prompt"`
	Agent        string   `json:"agent"`
	Agents       []string `json:"agents"`
	SessionCount int      `json:"session_count"`
	TotalSteps   int      `json:"total_steps"`
}

// userCommit represents a single commit returned by the commits API.
type userCommit struct {
	CommitSHA              string                 `json:"commit_sha"`
	CommitMsg              *string                `json:"commit_message"`
	CommitAuthorUsername   *string                `json:"commit_author_username"`
	CommitDate             *string                `json:"commit_date"`
	Additions              int                    `json:"additions"`
	Deletions              int                    `json:"deletions"`
	FilesChanged           int                    `json:"files_changed"`
	Checkpoints            []userCommitCheckpoint `json:"checkpoints"`
	RepoFullName           string                 `json:"repo_full_name"`
	IsPrivate              bool                   `json:"is_private"`
	CheckpointRepoFullName *string                `json:"checkpoint_repo_full_name"`
}

// userCommitsResponse is the API response for GET /api/v1/cache/user/commits.
type userCommitsResponse struct {
	Commits   []userCommit `json:"commits"`
	Timeframe string       `json:"timeframe"`
	UpdatedAt string       `json:"updated_at"`
}

// Computed types used for rendering.

type contributionStats struct {
	Tasks         int
	Throughput    float64 // avg tokens/checkpoint in thousands
	Iteration     float64 // avg sessions/checkpoint
	ContinuityH  float64 // peak session length in hours
	Streak        int     // longest consecutive days
	CurrentStreak int     // current streak from today
}

type repoContribution struct {
	Repo   string
	Total  int
	Agents map[string]int // agentID -> checkpoint count
}

// commitDay groups commits by date for display.
type commitDay struct {
	Date    string
	Commits []userCommit
}

package cli

import (
	"context"
	"fmt"
	"io"
	"sort"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/spf13/cobra"
)

func newStatsCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "stats",
		Short: "Show your activity overview",
		Long:  "Display checkpoint stats, repository breakdown, and recent commits from entire.io",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runStats(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr())
		},
	}
	return cmd
}

func runStats(ctx context.Context, w, errW io.Writer) error {
	client, err := NewAuthenticatedAPIClient(false)
	if err != nil {
		fmt.Fprintln(errW, "Not logged in. Run 'entire login' to authenticate.")
		return NewSilentError(err)
	}

	checkpoints, streakDates, err := fetchCheckpoints(ctx, client)
	if err != nil {
		return fmt.Errorf("fetch checkpoints: %w", err)
	}

	commits, err := fetchCommits(ctx, client)
	if err != nil {
		return fmt.Errorf("fetch commits: %w", err)
	}

	stats := computeContributionStats(checkpoints, streakDates)
	repos := computeRepoContributions(checkpoints)
	days := groupCommitsByDay(commits)

	sty := newStatsStyles(w)
	renderStats(w, sty, stats, repos, days, len(checkpoints))

	return nil
}

const (
	statsTimeframe = "last-month"
	statsLimit     = 500
)

func fetchCheckpoints(ctx context.Context, client *api.Client) ([]userCheckpoint, []string, error) {
	path := fmt.Sprintf("/api/v1/cache/user/checkpoints?timeframe=%s&limit=%d", statsTimeframe, statsLimit)
	resp, err := client.Get(ctx, path)
	if err != nil {
		return nil, nil, err
	}
	defer resp.Body.Close()

	if err := api.CheckResponse(resp); err != nil {
		return nil, nil, err
	}

	var result userCheckpointsResponse
	if err := api.DecodeJSON(resp, &result); err != nil {
		return nil, nil, err
	}
	return result.Checkpoints, result.StreakDates, nil
}

func fetchCommits(ctx context.Context, client *api.Client) ([]userCommit, error) {
	path := fmt.Sprintf("/api/v1/cache/user/commits?timeframe=%s&limit=%d", statsTimeframe, statsLimit)
	resp, err := client.Get(ctx, path)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	if err := api.CheckResponse(resp); err != nil {
		return nil, err
	}

	var result userCommitsResponse
	if err := api.DecodeJSON(resp, &result); err != nil {
		return nil, err
	}
	return result.Commits, nil
}

// computeContributionStats mirrors the frontend's computeStats + computeStreaks.
func computeContributionStats(checkpoints []userCheckpoint, streakDates []string) contributionStats {
	stats := contributionStats{}
	if len(checkpoints) == 0 {
		return stats
	}

	stats.Tasks = len(checkpoints)

	// Throughput: avg total tokens per checkpoint (in thousands)
	var tokenSum int
	var tokenCount int
	for _, cp := range checkpoints {
		if cp.InputTokens != nil || cp.OutputTokens != nil {
			tokens := derefOr(cp.InputTokens, 0) + derefOr(cp.OutputTokens, 0)
			tokenSum += tokens
			tokenCount++
		}
	}
	if tokenCount > 0 {
		stats.Throughput = float64(tokenSum) / float64(tokenCount) / 1000.0
	}

	// Iteration: avg session_count per checkpoint
	var sessionSum int
	for _, cp := range checkpoints {
		sessionSum += derefOr(cp.SessionCount, 1)
	}
	stats.Iteration = float64(sessionSum) / float64(len(checkpoints))

	// Continuity: max(steps) * 2 / 60 (2 min/step estimate)
	var maxSteps int
	for _, cp := range checkpoints {
		s := derefOr(cp.Steps, 1)
		if s > maxSteps {
			maxSteps = s
		}
	}
	stats.ContinuityH = float64(maxSteps) * 2.0 / 60.0

	// Streaks from streakDates
	stats.Streak, stats.CurrentStreak = computeStreaks(streakDates)

	return stats
}

// computeStreaks mirrors the frontend's computeStreaks.
func computeStreaks(timestamps []string) (longest, current int) {
	if len(timestamps) == 0 {
		return 0, 0
	}

	// Collect unique local dates
	dateSet := make(map[string]struct{})
	for _, ts := range timestamps {
		t, err := time.Parse(time.RFC3339, ts)
		if err != nil {
			t, err = time.Parse(time.RFC3339Nano, ts)
			if err != nil {
				continue
			}
		}
		dateSet[t.Local().Format("2006-01-02")] = struct{}{}
	}

	if len(dateSet) == 0 {
		return 0, 0
	}

	// Current streak: from today or yesterday backward
	today := time.Now().Local().Format("2006-01-02")
	check := time.Now().Local()
	if _, ok := dateSet[today]; !ok {
		check = check.AddDate(0, 0, -1)
	}
	for {
		if _, ok := dateSet[check.Format("2006-01-02")]; !ok {
			break
		}
		current++
		check = check.AddDate(0, 0, -1)
	}

	// Longest streak
	dates := make([]string, 0, len(dateSet))
	for d := range dateSet {
		dates = append(dates, d)
	}
	sort.Strings(dates)

	run := 1
	longest = 1
	for i := 1; i < len(dates); i++ {
		prev, _ := time.Parse("2006-01-02", dates[i-1])
		curr, _ := time.Parse("2006-01-02", dates[i])
		if curr.Sub(prev).Hours() <= 25 { // 1 day with some tolerance
			run++
		} else {
			run = 1
		}
		if run > longest {
			longest = run
		}
	}

	return longest, current
}

// computeRepoContributions groups checkpoints by repo with agent breakdown.
func computeRepoContributions(checkpoints []userCheckpoint) []repoContribution {
	byRepo := make(map[string]*repoContribution)

	for _, cp := range checkpoints {
		rc, ok := byRepo[cp.RepoFullName]
		if !ok {
			rc = &repoContribution{
				Repo:   cp.RepoFullName,
				Agents: make(map[string]int),
			}
			byRepo[cp.RepoFullName] = rc
		}
		rc.Total++
		agentID := normalizeAgentID(cp.Agent)
		rc.Agents[agentID]++
	}

	result := make([]repoContribution, 0, len(byRepo))
	for _, rc := range byRepo {
		result = append(result, *rc)
	}
	sort.Slice(result, func(i, j int) bool {
		return result[i].Total > result[j].Total
	})
	return result
}

// groupCommitsByDay groups commits by local date, newest first.
func groupCommitsByDay(commits []userCommit) []commitDay {
	byDate := make(map[string][]userCommit)
	var dateOrder []string

	for _, c := range commits {
		date := "unknown"
		if c.CommitDate != nil {
			if t, err := time.Parse(time.RFC3339, *c.CommitDate); err == nil {
				date = t.Local().Format("2006-01-02")
			} else if t, err := time.Parse(time.RFC3339Nano, *c.CommitDate); err == nil {
				date = t.Local().Format("2006-01-02")
			}
		}
		if _, exists := byDate[date]; !exists {
			dateOrder = append(dateOrder, date)
		}
		byDate[date] = append(byDate[date], c)
	}

	// Sort dates newest first
	sort.Sort(sort.Reverse(sort.StringSlice(dateOrder)))

	result := make([]commitDay, 0, len(dateOrder))
	for _, d := range dateOrder {
		result = append(result, commitDay{Date: d, Commits: byDate[d]})
	}
	return result
}

// normalizeAgentID maps an agent string to a known agent ID, matching the frontend logic.
func normalizeAgentID(agent *string) string {
	if agent == nil {
		return "unknown"
	}
	return normalizeAgentString(*agent)
}

func normalizeAgentString(s string) string {
	if s == "" {
		return "unknown"
	}

	known := map[string]string{
		"claude":     "claude",
		"claudecode": "claude",
		"gemini":     "gemini",
		"geminicli":  "gemini",
		"amp":        "amp",
		"codex":      "codex",
		"opencode":   "opencode",
		"copilot":    "copilot",
		"copilotcli": "copilot",
		"pi":         "pi",
		"cursor":     "cursor",
		"droid":      "droid",
		"kiro":       "kiro",
	}

	// lowercase, strip separators
	lower := ""
	for _, r := range s {
		if r == ' ' || r == '-' || r == '_' {
			continue
		}
		if r >= 'A' && r <= 'Z' {
			lower += string(r + 32)
		} else {
			lower += string(r)
		}
	}

	if id, ok := known[lower]; ok {
		return id
	}

	// Strip common suffixes: "code", "cli"
	for _, suffix := range []string{"code", "cli"} {
		if len(lower) > len(suffix) && lower[len(lower)-len(suffix):] == suffix {
			stripped := lower[:len(lower)-len(suffix)]
			if id, ok := known[stripped]; ok {
				return id
			}
		}
	}

	// Factory AI Droid
	if len(lower) >= 15 && lower[:15] == "factoryaidroid" {
		return "droid"
	}

	return "unknown"
}

func derefOr(p *int, def int) int {
	if p == nil {
		return def
	}
	return *p
}

