104	
105		// Throughput: avg total tokens per checkpoint (in thousands)
106		var tokenSum int
107		var tokenCount int
108		for _, cp := range checkpoints {
109			if cp.InputTokens != nil || cp.OutputTokens != nil {
110				tokens := derefOr(cp.InputTokens, 0) + derefOr(cp.OutputTokens, 0)
111				tokenSum += tokens
112				tokenCount++
113			}
114		}
115		if tokenCount > 0 {
116			stats.Throughput = float64(tokenSum) / float64(tokenCount) / 1000.0
117		}
