119		// Iteration: avg session_count per checkpoint
120		var sessionSum int
121		for _, cp := range checkpoints {
122			sessionSum += derefOr(cp.SessionCount, 1)
123		}
124		stats.Iteration = float64(sessionSum) / float64(len(checkpoints))
