148		// Collect unique local dates
149		dateSet := make(map[string]struct{})
150		for _, ts := range timestamps {
151			t, err := time.Parse(time.RFC3339, ts)
152			if err != nil {
153				t, err = time.Parse(time.RFC3339Nano, ts)
154				if err != nil {
