156				}
157			}
158			dateSet[t.Local().Format("2006-01-02")] = struct{}{}
159		}
160	
161		if len(dateSet) == 0 {
162			return 0, 0
163		}
164	
165		// Current streak: from today or yesterday backward
166		today := time.Now().Local().Format("2006-01-02")
167		check := time.Now().Local()
168		if _, ok := dateSet[today]; !ok {
169			check = check.AddDate(0, 0, -1)
170		}
171		for {
172			if _, ok := dateSet[check.Format("2006-01-02")]; !ok {
173				break
174			}
175			current++
176			check = check.AddDate(0, 0, -1)
177		}
