205	func computeRepoContributions(checkpoints []userCheckpoint) []repoContribution {
206		byRepo := make(map[string]*repoContribution)
207	
208		for _, cp := range checkpoints {
209			rc, ok := byRepo[cp.RepoFullName]
210			if !ok {
211				rc = &repoContribution{
212					Repo:   cp.RepoFullName,
213					Agents: make(map[string]int),
214				}
215				byRepo[cp.RepoFullName] = rc
216			}
217			rc.Total++
218			agentID := normalizeAgentID(cp.Agent)
219			rc.Agents[agentID]++
220		}
221	
222		result := make([]repoContribution, 0, len(byRepo))
223		for _, rc := range byRepo {
224			result = append(result, *rc)
225		}
226		sort.Slice(result, func(i, j int) bool {
227			return result[i].Total > result[j].Total
228		})
229		return result
230	}
