232	// groupCommitsByDay groups commits by local date, newest first.
233	func groupCommitsByDay(commits []userCommit) []commitDay {
234		byDate := make(map[string][]userCommit)
235		var dateOrder []string
236	
237		for _, c := range commits {
238			date := "unknown"
239			if c.CommitDate != nil {
240				if t, err := time.Parse(time.RFC3339, *c.CommitDate); err == nil {
241					date = t.Local().Format("2006-01-02")
242				} else if t, err := time.Parse(time.RFC3339Nano, *c.CommitDate); err == nil {
243					date = t.Local().Format("2006-01-02")
244				}
245			}
246			if _, exists := byDate[date]; !exists {
247				dateOrder = append(dateOrder, date)
248			}
249			byDate[date] = append(byDate[date], c)
250		}
251	
252		// Sort dates newest first
253		sort.Sort(sort.Reverse(sort.StringSlice(dateOrder)))
254	
255		result := make([]commitDay, 0, len(dateOrder))
256		for _, d := range dateOrder {
257			result = append(result, commitDay{Date: d, Commits: byDate[d]})
258		}
259		return result
260	}
