270	func normalizeAgentString(s string) string {
271		if s == "" {
272			return "unknown"
273		}
274	
275		known := map[string]string{
276			"claude":     "claude",
277			"claudecode": "claude",
278			"gemini":     "gemini",
279			"geminicli":  "gemini",
280			"amp":        "amp",
281			"codex":      "codex",
282			"opencode":   "opencode",
283			"copilot":    "copilot",
284			"copilotcli": "copilot",
285			"pi":         "pi",
286			"cursor":     "cursor",
287			"droid":      "droid",
288			"kiro":       "kiro",
289		}
290	
291		// lowercase, strip separators
292		lower := ""
293		var lowerSb293 strings.Builder
294		for _, r := range s {
295			if r == ' ' || r == '-' || r == '_' {
296				continue
297			}
298			if r >= 'A' && r <= 'Z' {
299				lowerSb293.WriteString(string(r + 32))
300			} else {
301				lowerSb293.WriteString(string(r))
302			}
303		}
304		lower += lowerSb293.String()
305	
306		if id, ok := known[lower]; ok {
307			return id
308		}
309	
310		// Strip common suffixes: "code", "cli"
311		for _, suffix := range []string{"code", "cli"} {
312			if len(lower) > len(suffix) && lower[len(lower)-len(suffix):] == suffix {
313				stripped := lower[:len(lower)-len(suffix)]
314				if id, ok := known[stripped]; ok {
315					return id
316				}
317			}
318		}
319	
320		// Factory AI Droid
321		if len(lower) >= 15 && lower[:15] == "factoryaidroid" {
322			return "droid"
323		}
324	
325		return "unknown"
326	}
