105	func renderStatCards(w io.Writer, sty statsStyles, stats contributionStats) {
106		// Render 4 stat cards in a single row.
107		cards := []struct {
108			label string
109			value string
110			unit  string
111			desc  string
112		}{
113			{"THROUGHPUT", fmt.Sprintf("%.1f", stats.Throughput), "k", "Avg. tokens/checkpoint"},
114			{"ITERATION", fmt.Sprintf("%.1f", stats.Iteration), "x", "Avg steps/checkpoint"},
115			{"CONTINUITY", fmt.Sprintf("%.1f", stats.ContinuityH), "h", "Peak session length"},
116			{"STREAK", strconv.Itoa(stats.Streak), " day", fmt.Sprintf("%d current", stats.CurrentStreak)},
117		}
118	
119		// Calculate card width: distribute evenly across terminal width
120		cardWidth := (sty.width - 3) / 4 // 3 separators
121		if cardWidth < 16 {
122			cardWidth = 16
123		}
124	
125		var topParts, midParts, botParts []string
126		for _, c := range cards {
127			lbl := padOrTruncate(c.label, cardWidth)
128			val := c.value + c.unit
129			valLine := padOrTruncate(val, cardWidth)
130			dsc := padOrTruncate(c.desc, cardWidth)
131	
132			topParts = append(topParts, sty.render(sty.label, lbl))
133			midParts = append(midParts, sty.render(sty.value, c.value)+sty.render(sty.unit, c.unit)+
134				strings.Repeat(" ", max(0, cardWidth-len(c.value)-len(c.unit))))
135			_ = valLine // use the formatted parts instead
136			botParts = append(botParts, sty.render(sty.desc, dsc))
137		}
138	
139		sep := sty.render(sty.dim, " │ ")
140		fmt.Fprintln(w, strings.Join(topParts, sep))
141		fmt.Fprintln(w, strings.Join(midParts, sep))
142		fmt.Fprintln(w, strings.Join(botParts, sep))
143	}
