145	func renderAgentBreakdown(w io.Writer, sty statsStyles, totalCheckpoints int, repos []repoContribution) {
146		// Aggregate agent counts across all repos.
147		agentTotals := make(map[string]int)
148		for _, r := range repos {
149			for agent, count := range r.Agents {
150				agentTotals[agent] += count
151			}
152		}
153	
154		if totalCheckpoints == 0 {
155			return
156		}
157	
158		// Build breakdown line: "Claude Code 36% · Codex 52% · ..."
159		var parts []string
160		for _, id := range agentOrder {
161			count, ok := agentTotals[id]
162			if !ok || count == 0 {
163				continue
164			}
165			pct := float64(count) / float64(totalCheckpoints) * 100
166			display := agentDisplayMap[id]
167			if sty.colorEnabled {
168				agentStyle := lipgloss.NewStyle().Foreground(lipgloss.Color(display.Color))
169				parts = append(parts, agentStyle.Render(fmt.Sprintf("● %s %d%%", display.Label, int(math.Round(pct)))))
170			} else {
171				parts = append(parts, fmt.Sprintf("%s %d%%", display.Label, int(math.Round(pct))))
172			}
173		}
174	
175		fmt.Fprintf(w, "%s  %s\n",
176			sty.render(sty.label, "CONTRIBUTIONS"),
177			sty.render(sty.muted, fmt.Sprintf("%d checkpoints", totalCheckpoints)))
178		fmt.Fprintln(w, strings.Join(parts, sty.render(sty.dim, "  ")))
