181	func renderRepoChart(w io.Writer, sty statsStyles, repos []repoContribution) {
182		if len(repos) == 0 {
183			return
184		}
185	
186		fmt.Fprintln(w, sty.render(sty.label, "REPOSITORIES"))
187	
188		maxRepos := 5
189		if len(repos) < maxRepos {
190			maxRepos = len(repos)
191		}
192		display := repos[:maxRepos]
193	
194		// Find max count for scaling
195		maxCount := display[0].Total
196	
197		// Find longest repo name for alignment
198		maxNameLen := 0
199		for _, r := range display {
200			if len(r.Repo) > maxNameLen {
201				maxNameLen = len(r.Repo)
202			}
203		}
204		if maxNameLen > 30 {
205			maxNameLen = 30
206		}
207	
208		// Bar width: total width - name column - count column - spacing
209		countWidth := len(strconv.Itoa(maxCount))
210		barWidth := sty.width - maxNameLen - countWidth - 4
211		if barWidth < 10 {
212			barWidth = 10
213		}
214	
215		for _, r := range display {
216			name := r.Repo
217			if len(name) > maxNameLen {
218				name = name[:maxNameLen-1] + "…"
219			}
220			name = fmt.Sprintf("%-*s", maxNameLen, name)
221	
222			// Build the bar with agent-colored segments
223			bar := renderAgentBar(sty, r.Agents, maxCount, barWidth)
224	
225			count := fmt.Sprintf("%*d", countWidth, r.Total)
226	
227			fmt.Fprintf(w, "%s %s %s\n",
228				sty.render(sty.repoNm, name),
229				bar,
230				sty.render(sty.muted, count))
231		}
232	}
