234	func renderAgentBar(sty statsStyles, agents map[string]int, maxCount, barWidth int) string {
235		if maxCount == 0 {
236			return strings.Repeat(" ", barWidth)
237		}
238	
239		var b strings.Builder
240	
241		filled := 0
242		for _, id := range agentOrder {
243			count, ok := agents[id]
244			if !ok || count == 0 {
245				continue
246			}
247			segWidth := int(math.Round(float64(count) / float64(maxCount) * float64(barWidth)))
248			if segWidth < 1 && count > 0 {
249				segWidth = 1
250			}
251			if filled+segWidth > barWidth {
252				segWidth = barWidth - filled
253			}
254			if segWidth <= 0 {
255				continue
256			}
257	
258			display := agentDisplayMap[id]
259			seg := strings.Repeat(string(display.Char), segWidth)
260			if sty.colorEnabled {
261				agentStyle := lipgloss.NewStyle().Foreground(lipgloss.Color(display.Color))
262				b.WriteString(agentStyle.Render(seg))
263			} else {
264				b.WriteString(seg)
265			}
266			filled += segWidth
267		}
268	
269		// Fill remaining with dim background
270		if filled < barWidth {
271			bg := strings.Repeat("░", barWidth-filled)
272			b.WriteString(sty.render(sty.dim, bg))
273		}
274	
275		return b.String()
276	}
