278	func renderCommitList(w io.Writer, sty statsStyles, days []commitDay) {
279		if len(days) == 0 {
280			return
281		}
282	
283		maxDays := 3
284		if len(days) < maxDays {
285			maxDays = len(days)
286		}
287	
288		for _, day := range days[:maxDays] {
289			displayDate := formatCommitDate(day.Date)
290			commitWord := "commits"
291			if len(day.Commits) == 1 {
292				commitWord = "commit"
293			}
294	
295			fmt.Fprintf(w, "%s  %s\n",
296				sty.render(sty.bold, displayDate),
297				sty.render(sty.muted, fmt.Sprintf("%d %s", len(day.Commits), commitWord)))
298	
299			for _, c := range day.Commits {
300				sha := c.CommitSHA
301				if len(sha) > 7 {
302					sha = sha[:7]
303				}
304	
305				msg := "(no message)"
306				if c.CommitMsg != nil && *c.CommitMsg != "" {
307					msg = firstLine(*c.CommitMsg)
308				}
309	
310				// Truncate message to fit
311				maxMsg := sty.width - 10 - len(c.RepoFullName) - 20
312				if maxMsg < 20 {
313					maxMsg = 20
314				}
315				if len(msg) > maxMsg {
316					msg = msg[:maxMsg-3] + "..."
317				}
318	
319				// Agent badges
320				var badges []string
321				uniqueAgents := uniqueCommitAgents(c)
322				for _, a := range uniqueAgents {
323					display := agentDisplayMap[a]
324					if sty.colorEnabled {
325						agentStyle := lipgloss.NewStyle().Foreground(lipgloss.Color(display.Color))
326						badges = append(badges, agentStyle.Render(display.Label))
327					} else {
328						badges = append(badges, display.Label)
329					}
330				}
331	
332				// Diff stats
333				diffStats := fmt.Sprintf("+%d / -%d", c.Additions, c.Deletions)
334				fileStats := fmt.Sprintf("%d files", c.FilesChanged)
335				if c.FilesChanged == 1 {
336					fileStats = "1 file"
337				}
338	
339				// Checkpoint count
340				cpCount := len(c.Checkpoints)
341				cpStr := ""
342				if cpCount > 0 {
343					if cpCount == 1 {
344						cpStr = "1 checkpoint"
345					} else {
346						cpStr = fmt.Sprintf("%d checkpoints", cpCount)
347					}
348				}
349	
350				// Line 1: hash  message  repo  [agent badges]
351				fmt.Fprintf(w, "%s %s %s",
352					sty.render(sty.commitH, sha),
353					sty.render(sty.commitM, msg),
354					sty.render(sty.muted, c.RepoFullName))
355				for _, badge := range badges {
356					fmt.Fprintf(w, "  %s", badge)
357				}
358				fmt.Fprintln(w)
359	
360				// Line 2: stats
361				var statParts []string
362				statParts = append(statParts,
363					sty.render(sty.add, fmt.Sprintf("+%d", c.Additions))+
364						sty.render(sty.muted, " / ")+
365						sty.render(sty.del, fmt.Sprintf("-%d", c.Deletions)))
366				_ = diffStats // used the colored version above
367				statParts = append(statParts, sty.render(sty.muted, fileStats))
368				if cpStr != "" {
369					statParts = append(statParts, sty.render(sty.muted, cpStr))
370				}
371	
372				fmt.Fprintf(w, "        %s\n", strings.Join(statParts, sty.render(sty.dim, "  ")))
373			}
374			fmt.Fprintln(w)
375		}
376	}
