378	func uniqueCommitAgents(c userCommit) []string {
379		seen := make(map[string]struct{})
380		var result []string
381		for _, cp := range c.Checkpoints {
382			for _, a := range cp.Agents {
383				id := normalizeAgentString(a)
384				if _, ok := seen[id]; !ok {
385					seen[id] = struct{}{}
386					result = append(result, id)
387				}
388			}
389		}
390		// Stable sort
391		sort.Strings(result)
392		return result
393	}
