395	func formatCommitDate(dateStr string) string {
396		t, err := time.Parse("2006-01-02", dateStr)
397		if err != nil {
398			return dateStr
399		}
400		now := time.Now().Local()
401		today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
402		d := today.Sub(t)
403	
404		switch {
405		case d < 24*time.Hour:
406			return t.Format("Monday 2 Jan") + " (today)"
407		case d < 48*time.Hour:
408			return t.Format("Monday 2 Jan") + " (yesterday)"
409		default:
410			return t.Format("Monday 2 Jan")
411		}
412	}
413	
414	func padOrTruncate(s string, width int) string {
415		if len(s) > width {
416			return s[:width-1] + "…"
417		}
418		return s + strings.Repeat(" ", width-len(s))
419	}
