149		}
150	
151		// Collect unique local dates
152		dateSet := make(map[string]struct{})
153		for _, ts := range timestamps {
154			t, err := time.Parse(time.RFC3339, ts)
155			if err != nil {
156				t, err = time.Parse(time.RFC3339Nano, ts)
157				if err != nil {
158					continue
159				}
160			}
161			dateSet[t.Local().Format("2006-01-02")] = struct{}{}
162		}
163	
164		if len(dateSet) == 0 {
165			return 0, 0
166		}
167	
168		// Current streak: from today or yesterday backward
169		today := time.Now().Local().Format("2006-01-02")
170		check := time.Now().Local()
171		if _, ok := dateSet[today]; !ok {
172			check = check.AddDate(0, 0, -1)
173		}
174		for {
175			if _, ok := dateSet[check.Format("2006-01-02")]; !ok {
176				break
177			}
178			current++
179			check = check.AddDate(0, 0, -1)
180		}
181	
182		// Longest streak
183		dates := make([]string, 0, len(dateSet))
184		for d := range dateSet {
185			dates = append(dates, d)
186		}
187		sort.Strings(dates)
188	
189		run := 1
190		longest = 1
191		for i := 1; i < len(dates); i++ {
192			prev, errP := time.Parse("2006-01-02", dates[i-1])
193			curr, errC := time.Parse("2006-01-02", dates[i])
194			if errP != nil || errC != nil {
195				run = 1
196				continue
197			}
198			if curr.Sub(prev).Hours() <= 25 { // 1 day with some tolerance
199				run++
200			} else {
201				run = 1
202			}
203			if run > longest {
204				longest = run
205			}
206		}
207	
208		return longest, current
209	}
