277	func normalizeAgentString(s string) string {
278		if s == "" {
279			return agentUnknown
280		}
281	
282		known := map[string]string{
283			"claude":     "claude",
284			"claudecode": "claude",
285			"gemini":     "gemini",
286			"geminicli":  "gemini",
287			"amp":        "amp",
288			"codex":      "codex",
289			"opencode":   "opencode",
290			"copilot":    "copilot",
291			"copilotcli": "copilot",
292			"pi":         "pi",
293			"cursor":     "cursor",
294			"droid":      "droid",
295			"kiro":       "kiro",
296		}
297	
298		// lowercase, strip separators
299		var sb strings.Builder
300		for _, r := range s {
301			if r == ' ' || r == '-' || r == '_' {
302				continue
303			}
304			if r >= 'A' && r <= 'Z' {
305				sb.WriteByte(byte(r + 32))
306			} else {
307				sb.WriteRune(r)
308			}
309		}
310		lower := sb.String()
311	
312		if id, ok := known[lower]; ok {
313			return id
314		}
315	
316		// Strip common suffixes: "code", "cli"
317		for _, suffix := range []string{"code", "cli"} {
318			if len(lower) > len(suffix) && lower[len(lower)-len(suffix):] == suffix {
319				stripped := lower[:len(lower)-len(suffix)]
320				if id, ok := known[stripped]; ok {
321					return id
322				}
323			}
324		}
325	
326		// Factory AI Droid
327		if len(lower) >= 15 && lower[:15] == "factoryaidroid" {
328			return "droid"
329		}
330	
331		return agentUnknown
332	}
