373	func uniqueCommitAgents(c userCommit) []string {
374		seen := make(map[string]struct{})
375		var result []string
376		for _, cp := range c.Checkpoints {
377			for _, a := range cp.Agents {
378				id := normalizeAgentString(a)
379				if _, ok := seen[id]; !ok {
380					seen[id] = struct{}{}
381					result = append(result, id)
382				}
383			}
384		}
385		// Stable sort
386		sort.Strings(result)
387		return result
388	}
