390	func formatCommitDate(dateStr string) string {
391		t, err := time.Parse("2006-01-02", dateStr)
392		if err != nil {
393			return dateStr
394		}
395		now := time.Now().Local()
396		today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
397		d := today.Sub(t)
398	
399		switch {
400		case d < 24*time.Hour:
401			return t.Format("Monday 2 Jan") + " (today)"
402		case d < 48*time.Hour:
403			return t.Format("Monday 2 Jan") + " (yesterday)"
404		default:
405			return t.Format("Monday 2 Jan")
406		}
407	}
408	
409	func padOrTruncate(s string, width int) string {
410		if len(s) > width {
411			return s[:width-1] + "…"
412		}
413		return s + strings.Repeat(" ", width-len(s))
414	}
