116			desc  string
117		}{
118			{"THROUGHPUT", fmt.Sprintf("%.1f", stats.Throughput), "k", "Avg. tokens/checkpoint"},
119			{"ITERATION", fmt.Sprintf("%.1f", stats.Iteration), "x", "Avg sessions/checkpoint"},
120			{"CONTINUITY", fmt.Sprintf("%.1f", stats.ContinuityH), "h", "Peak session length"},
121			{"STREAK", strconv.Itoa(stats.Streak), " day", fmt.Sprintf("%d current", stats.CurrentStreak)},
122		}
123	
124		cardWidth := (sty.width - 3) / 4 // 3 separators
125		if cardWidth < 16 {
126			cardWidth = 16
127		}
128	
129		var topParts, midParts, botParts []string
130		for _, c := range cards {
131			lbl := padOrTruncate(c.label, cardWidth)
132			dsc := padOrTruncate(c.desc, cardWidth)
133	
134			topParts = append(topParts, sty.render(sty.label, lbl))
135			midParts = append(midParts, sty.render(sty.value, c.value)+sty.render(sty.unit, c.unit)+
136				strings.Repeat(" ", max(0, cardWidth-len(c.value)-len(c.unit))))
137			botParts = append(botParts, sty.render(sty.desc, dsc))
138		}
