225	func renderAgentBar(sty statsStyles, agents map[string]int, maxCount, barWidth int) string {
226		if maxCount == 0 {
227			return strings.Repeat(" ", barWidth)
228		}
229	
230		var b strings.Builder
231	
232		filled := 0
233		for _, id := range agentOrder {
234			count, ok := agents[id]
235			if !ok || count == 0 {
236				continue
237			}
238			segWidth := int(math.Round(float64(count) / float64(maxCount) * float64(barWidth)))
239			if segWidth < 1 && count > 0 {
240				segWidth = 1
241			}
242			if filled+segWidth > barWidth {
243				segWidth = barWidth - filled
244			}
245			if segWidth <= 0 {
246				continue
247			}
248	
249			display := agentDisplayMap[id]
250			seg := strings.Repeat(string(display.Char), segWidth)
251			b.WriteString(sty.renderAgent(id, seg))
252			filled += segWidth
253		}
254	
255		if filled < barWidth {
256			b.WriteString(sty.render(sty.dim, strings.Repeat("░", barWidth-filled)))
257		}
258	
259		return b.String()
260	}
