// Option A: Sized dot scatter
// ============================================================

func renderOptionA(points []dataPoint, width int) string {
	var b strings.Builder

	now := time.Now().Local()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
	numDays := 30

	// Hour rows: 0, 6, 12, 18 (4 bands of 6 hours each)
	hourBands := []struct {
		label string
		lo, hi int
	}{
		{" 0", 0, 5},
		{" 6", 6, 11},
		{"12", 12, 17},
		{"18", 18, 23},
	}

	// Build grid: [band][day] -> best (value, agentID)
	type cell struct {
		value   int
		agentID string
	}
	grid := make([][]cell, len(hourBands))
	for i := range grid {
		grid[i] = make([]cell, numDays)
	}

	for _, p := range points {
		dayIdx := int(today.Sub(time.Date(p.date.Year(), p.date.Month(), p.date.Day(), 0, 0, 0, 0, p.date.Location())).Hours() / 24)
		col := numDays - 1 - dayIdx
		if col < 0 || col >= numDays {
			continue
		}
		band := -1
		for i, hb := range hourBands {
			if p.hour >= hb.lo && p.hour <= hb.hi {
				band = i
				break
			}
		}
		if band < 0 {
			continue
		}
		if p.value > grid[band][col].value {
			grid[band][col] = cell{value: p.value, agentID: p.agentID}
		}
	}

	// Characters for sizes
	sizeChars := []string{" ", "·", "•", "●", "⬤"}
	sizeFor := func(v int) int {
		switch {
		case v == 0:
			return 0
		case v <= 2:
			return 1
		case v <= 5:
			return 2
		case v <= 9:
			return 3
		default:
			return 4
		}
	}

	labelWidth := 3
	// Scale columns to fit width
	availCols := width - labelWidth - 2
	colWidth := availCols / numDays
	if colWidth < 1 {
		colWidth = 1
	}

	// Title
	b.WriteString(lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true).Render("CONTRIBUTIONS") + "\n")

	// Date axis labels
	b.WriteString(strings.Repeat(" ", labelWidth+1))
	startDate := today.AddDate(0, 0, -(numDays - 1))
	lastMonth := ""
	for d := 0; d < numDays; d++ {
		date := startDate.AddDate(0, 0, d)
		month := date.Format("Jan")
		if month != lastMonth {
			label := month
			if len(label) > colWidth*3 {
				label = label[:colWidth*3]
			}
			b.WriteString(label)
			d += len(label)/max(colWidth, 1)
			lastMonth = month
		} else {
			b.WriteString(strings.Repeat(" ", colWidth))
		}
	}
	b.WriteString("\n")

	// Grid rows
	dimStyle := lipgloss.NewStyle().Faint(true)
	for band, hb := range hourBands {
		b.WriteString(dimStyle.Render(hb.label) + " ")
		for col := 0; col < numDays; col++ {
			c := grid[band][col]
			sz := sizeFor(c.value)
			ch := sizeChars[sz]
			if sz == 0 {
				b.WriteString(strings.Repeat(" ", colWidth))
			} else {
				info := agents[c.agentID]
				styled := lipgloss.NewStyle().Foreground(lipgloss.Color(info.color)).Render(ch)
				b.WriteString(styled + strings.Repeat(" ", colWidth-1))
			}
		}
		b.WriteString("\n")
	}

	// Legend
	b.WriteString("\n")
	b.WriteString(dimStyle.Render("     · 1-2   • 3-5   ● 6-9   ⬤ 10+") + "\n")

	return b.String()
}

// ============================================================
// Option B: Braille scatter
// ============================================================

// Braille unicode block: U+2800 to U+28FF
// Each cell is 2 wide x 4 tall dots:
//   dot1 dot4
//   dot2 dot5
//   dot3 dot6
//   dot7 dot8
// Bit mapping: dot1=0x01, dot2=0x02, dot3=0x04, dot4=0x08,
//              dot5=0x10, dot6=0x20, dot7=0x40, dot8=0x80

func renderOptionB(points []dataPoint, width int) string {
	var b strings.Builder

	now := time.Now().Local()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
	numDays := 30

	labelWidth := 3
	chartCols := width - labelWidth - 2
	if chartCols < 20 {
		chartCols = 20
	}

	// Each braille char = 2 dots wide, 4 dots tall
	// X resolution: chartCols * 2 dots
	// Y resolution: we want 24 hours. Each braille char = 4 dots tall.
	// So we need 24/4 = 6 rows of braille chars (each row covers 4 hours)
	chartRows := 6 // 6 * 4 = 24 hours
	dotsX := chartCols * 2
	dotsY := chartRows * 4

	// Map data to dot grid
	type dotInfo struct {
		set     bool
		agentID string
		value   int
	}
	dotGrid := make([][]dotInfo, dotsY)
	for i := range dotGrid {
		dotGrid[i] = make([]dotInfo, dotsX)
	}

	for _, p := range points {
		dayIdx := int(today.Sub(time.Date(p.date.Year(), p.date.Month(), p.date.Day(), 0, 0, 0, 0, p.date.Location())).Hours() / 24)
		dayFromStart := numDays - 1 - dayIdx
		if dayFromStart < 0 || dayFromStart >= numDays {
			continue
		}

		// X position: map day to dot column
		dx := int(float64(dayFromStart) / float64(numDays) * float64(dotsX))
		if dx >= dotsX {
			dx = dotsX - 1
		}

		// Y position: hour maps directly to dot row
		dy := p.hour
		if dy >= dotsY {
			dy = dotsY - 1
		}

		// For larger values, draw bigger "bubbles" (fill adjacent dots)
		radius := 0
		if p.value >= 3 {
			radius = 1
		}
		if p.value >= 8 {
			radius = 2
		}

		for oy := -radius; oy <= radius; oy++ {
			for ox := -radius; ox <= radius; ox++ {
				// Circular mask
				if ox*ox+oy*oy > radius*radius+1 {
					continue
				}
				ny, nx := dy+oy, dx+ox
				if ny >= 0 && ny < dotsY && nx >= 0 && nx < dotsX {
					if p.value > dotGrid[ny][nx].value {
						dotGrid[ny][nx] = dotInfo{set: true, agentID: p.agentID, value: p.value}
					}
				}
			}
		}
	}

	// Convert dot grid to braille characters
	// Each braille char covers cols [cx*2, cx*2+1] and rows [cy*4 .. cy*4+3]
	b.WriteString(lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true).Render("CONTRIBUTIONS") + "\n")

	// Date axis
	b.WriteString(strings.Repeat(" ", labelWidth+1))
	startDate := today.AddDate(0, 0, -(numDays-1))
	lastMonth := ""
	for col := 0; col < chartCols; col++ {
		dayFrac := float64(col) / float64(chartCols) * float64(numDays)
		date := startDate.AddDate(0, 0, int(dayFrac))
		month := date.Format("Jan")
		if month != lastMonth {
			b.WriteString(month)
			col += len(month) - 1
			lastMonth = month
		} else {
			b.WriteString(" ")
		}
	}
	b.WriteString("\n")

	dimStyle := lipgloss.NewStyle().Faint(true)
	hourLabels := []string{" 0", " 4", " 8", "12", "16", "20"}

	for cy := 0; cy < chartRows; cy++ {
		b.WriteString(dimStyle.Render(hourLabels[cy]) + " ")

		for cx := 0; cx < chartCols; cx++ {
			var brailleCode rune = 0x2800
			// Determine dominant agent for this cell
			dominantAgent := ""
			maxVal := 0

			dotBits := [8]struct{ dy, dx int }{
				{0, 0}, {1, 0}, {2, 0}, {0, 1},
				{1, 1}, {2, 1}, {3, 0}, {3, 1},
			}

			for bit, offset := range dotBits {
				dy := cy*4 + offset.dy
				dx := cx*2 + offset.dx
				if dy < dotsY && dx < dotsX && dotGrid[dy][dx].set {
					brailleCode |= 1 << bit
					if dotGrid[dy][dx].value > maxVal {
						maxVal = dotGrid[dy][dx].value
						dominantAgent = dotGrid[dy][dx].agentID
					}
				}
			}

			ch := string(brailleCode)
			if brailleCode == 0x2800 {
				b.WriteString(" ")
			} else {
				info := agents[dominantAgent]
				b.WriteString(lipgloss.NewStyle().Foreground(lipgloss.Color(info.color)).Render(ch))
			}
		}
		b.WriteString("\n")
	}

	return b.String()
}

// ============================================================
// Agent legend (shared)
// ============================================================

func renderLegend(points []dataPoint, total int) string {
	counts := make(map[string]int)
	for _, p := range points {
		counts[p.agentID] += p.value
	}
	totalSteps := 0
	for _, v := range counts {
		totalSteps += v
	}

	var parts []string
	for _, id := range agentOrder {
		c := counts[id]
		if c == 0 {
			continue
		}
		pct := int(math.Round(float64(c) / float64(totalSteps) * 100))
		info := agents[id]
		style := lipgloss.NewStyle().Foreground(lipgloss.Color(info.color))
		parts = append(parts, style.Render(fmt.Sprintf("● %s %d%%", info.label, pct)))
	}
	return strings.Join(parts, "  ")
}

func main() {
	width := getWidth()
	points := generateSampleData()

	fmt.Println()
	fmt.Println(lipgloss.NewStyle().Bold(true).Underline(true).Render("═══ Option A: Sized Dot Scatter ═══"))
	fmt.Println()
	fmt.Println(renderOptionA(points, width))
	fmt.Println(renderLegend(points, len(points)))
	fmt.Println()

	fmt.Println()
	fmt.Println(lipgloss.NewStyle().Bold(true).Underline(true).Render("═══ Option B: Braille Scatter ═══"))
	fmt.Println()
	fmt.Println(renderOptionB(points, width))
	fmt.Println(renderLegend(points, len(points)))
	fmt.Println()
}

